package com.nexodb.ui;

import static com.nexodb.util.I18n.tr;
import com.nexodb.db.*;
import com.nexodb.model.ConnectionProfile;
import javax.swing.*;
import javax.swing.table.*;
import java.awt.*;
import java.nio.file.*;
import java.util.*;
import java.util.List;

public final class CsvImportDialog extends JDialog {
    private final ConnectionProfile profile;private final String database;private final char[] password;private JdbcSession connection;
    private final JTextField file=new JTextField(),nullToken=new JTextField("\\N",8);private final JComboBox<String> table=new JComboBox<>(),delimiter=new JComboBox<>(new String[]{",",";","TAB"});private final JCheckBox header=new JCheckBox(tr("La primera fila contiene nombres"),true),empty=new JCheckBox(tr("Celdas vacías como NULL"),false);
    private final JButton browse=new JButton(tr("Examinar…")),review=new JButton(tr("Vista previa")),start=new JButton(tr("Importar")),close=new JButton(tr("Cerrar"));private final JLabel status=new JLabel(tr("Conectando…"));private final JTable data=new JTable(),mapping=new JTable();
    private final Map<String,CsvImportService.Column> columns=new LinkedHashMap<>();private CsvImportService.Preview preview;private SwingWorker<?,?> worker;private SqlTransferControl control;private String quote="\"";
    public CsvImportDialog(Frame owner,ConnectionProfile profile,char[] password,String database){super(owner,tr("Importar datos CSV / TSV"),true);this.profile=profile;this.database=database;this.password=password;setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);
        JPanel body=new JPanel(new BorderLayout(8,10));body.setBorder(new javax.swing.border.EmptyBorder(15,15,15,15));setContentPane(body);JPanel top=new JPanel(new GridLayout(0,1,4,6));top.add(new JLabel(profile.name()+" · "+database));JPanel path=new JPanel(new BorderLayout(6,0));path.add(file);path.add(browse,BorderLayout.EAST);top.add(path);JPanel options=new JPanel(new FlowLayout(FlowLayout.LEFT));options.add(new JLabel(tr("Tabla de destino:")));options.add(table);options.add(new JLabel(tr("Separador:")));options.add(delimiter);options.add(header);options.add(empty);options.add(new JLabel("NULL:"));options.add(nullToken);top.add(options);body.add(top,BorderLayout.NORTH);
        JSplitPane split=new JSplitPane(JSplitPane.VERTICAL_SPLIT,new JScrollPane(data),new JScrollPane(mapping));split.setDividerLocation(200);split.setResizeWeight(.5);body.add(split);JPanel footer=new JPanel(new BorderLayout());footer.add(status);JPanel actions=new JPanel(new FlowLayout(FlowLayout.RIGHT));actions.add(review);actions.add(start);actions.add(close);footer.add(actions,BorderLayout.EAST);body.add(footer,BorderLayout.SOUTH);
        browse.addActionListener(e->{JFileChooser chooser=new JFileChooser();chooser.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter("CSV / TSV","csv","tsv","txt"));if(chooser.showOpenDialog(this)==JFileChooser.APPROVE_OPTION){file.setText(chooser.getSelectedFile().toString());if(file.getText().toLowerCase(Locale.ROOT).endsWith(".tsv"))delimiter.setSelectedItem("TAB");preview();}});review.addActionListener(e->preview());start.addActionListener(e->importRows());close.addActionListener(e->close());addWindowListener(new java.awt.event.WindowAdapter(){public void windowClosing(java.awt.event.WindowEvent e){close();}});
        table.addActionListener(e->{if(worker==null&&connection!=null)loadColumns();});header.addActionListener(e->invalidatePreview());delimiter.addActionListener(e->invalidatePreview());file.getDocument().addDocumentListener(new javax.swing.event.DocumentListener(){public void insertUpdate(javax.swing.event.DocumentEvent e){invalidatePreview();}public void removeUpdate(javax.swing.event.DocumentEvent e){invalidatePreview();}public void changedUpdate(javax.swing.event.DocumentEvent e){}});
        setSize(1050,650);setLocationRelativeTo(owner);run(()->{try{connection=JdbcSession.open(profile,password);}finally{Arrays.fill(password,'\0');}quote=connection.connection().getMetaData().getIdentifierQuoteString();return SchemaMetadataReader.listObjects(connection,database);},objects->{for(var object:objects)if(object.type().equals("TABLE"))table.addItem(object.name());loadColumns();});
    }
    private void invalidatePreview(){preview=null;start.setEnabled(false);}
    private void loadColumns(){String name=Objects.toString(table.getSelectedItem(),"");if(name.isBlank())return;invalidatePreview();run(()->{List<CsvImportService.Column> list=new ArrayList<>();boolean catalog=SchemaMetadataReader.catalogNamespace(profile.type());try(var rows=connection.connection().getMetaData().getColumns(catalog?database:null,catalog?null:database,name.replace("_","\\_"),"%")){while(rows.next()){String generated="";try{generated=rows.getString("IS_GENERATEDCOLUMN");}catch(Exception ignored){}if(!"YES".equalsIgnoreCase(generated))list.add(new CsvImportService.Column(rows.getString("COLUMN_NAME"),rows.getInt("DATA_TYPE")));}}return list;},list->{columns.clear();for(var c:list)columns.put(c.name(),c);status.setText(tr("Selecciona un archivo y revisa las columnas."));});}
    private void preview(){if(worker!=null||file.getText().isBlank())return;char separator=delimiter.getSelectedItem().equals("TAB")?'\t':delimiter.getSelectedItem().toString().charAt(0);Path path;try{path=Path.of(file.getText());}catch(Exception error){error(error);return;}
        run(()->CsvImportService.preview(path,separator,header.isSelected()),value->{preview=value;DefaultTableModel display=new DefaultTableModel(value.headers().toArray(),0){public boolean isCellEditable(int r,int c){return false;}};value.rows().forEach(r->display.addRow(r.toArray()));data.setModel(display);DefaultTableModel map=new DefaultTableModel(new Object[]{tr("Columna del archivo"),tr("Columna de destino")},0){public boolean isCellEditable(int r,int c){return c==1;}};
            for(String source:value.headers())map.addRow(new Object[]{source,columns.keySet().stream().filter(c->c.equalsIgnoreCase(source)).findFirst().orElse("")});mapping.setModel(map);List<String> names=new ArrayList<>();names.add("");names.addAll(columns.keySet());mapping.getColumnModel().getColumn(1).setCellEditor(new DefaultCellEditor(new JComboBox<>(names.toArray(String[]::new))));start.setEnabled(true);status.setText(tr("Revisa el mapeo. Las columnas de destino vacías no se importan."));});
    }
    private void importRows(){if(preview==null||worker!=null)return;if(mapping.isEditing())mapping.getCellEditor().stopCellEditing();List<CsvImportService.Mapping> selected=new ArrayList<>();for(int i=0;i<mapping.getRowCount();i++){var target=columns.get(mapping.getValueAt(i,1));if(target!=null)selected.add(new CsvImportService.Mapping(i,target));}if(selected.isEmpty())return;
        if(!LicenseGate.ensure(this)||!Confirmations.ask(this,"Confirmar importación",profile.name()+" · "+database+"."+table.getSelectedItem()+"\n"+tr("Se agregarán los registros del archivo a esta tabla. ¿Importar?")))return;
        var options=new CsvImportService.Options(VisualQuery.qualified(database,table.getSelectedItem().toString(),quote),List.copyOf(selected),nullToken.getText(),empty.isSelected());var reviewed=preview;control=new SqlTransferControl();SqlTransferControl active=control;
        run(()->CsvImportService.importRows(connection.connection(),reviewed,options,active,count->SwingUtilities.invokeLater(()->status.setText(tr("%s registros leídos",count)))),count->{status.setText(tr("Importación completa: %s registros",count));JOptionPane.showMessageDialog(this,status.getText());});
    }
    private <T>void run(java.util.concurrent.Callable<T> operation,java.util.function.Consumer<T> success){if(worker!=null)return;setBusy(true);worker=new SwingWorker<T,Void>(){protected T doInBackground()throws Exception{return operation.call();}protected void done(){worker=null;setBusy(false);try{success.accept(get());}catch(Exception error){error(error.getCause()==null?error:error.getCause());}}};worker.execute();}
    private void setBusy(boolean value){for(JComponent c:List.of(table,file,browse,review,delimiter,header,empty,nullToken,mapping))c.setEnabled(!value);start.setEnabled(!value&&preview!=null);close.setText(tr(value?"Cancelar":"Cerrar"));}
    private void error(Throwable error){status.setText(tr("No se completó la importación."));JOptionPane.showMessageDialog(this,error.getMessage(),tr("Importar datos"),JOptionPane.ERROR_MESSAGE);}
    private void close(){if(worker!=null){if(control!=null){Thread t=new Thread(control::cancel,"nexodb-csv-cancel");t.setDaemon(true);t.start();}return;}Arrays.fill(password,'\0');if(connection!=null)try{connection.close();}catch(Exception ignored){}dispose();}
}
